/bin/bash -lc "python3 - <<'PY'
import json,re,collections
qs=[json.loads(x) for x in open('questions.jsonl')]
roots=set(re.findall(r'R3-\\d+', '\\n'.join(x['question'] for x in qs)))
revroots={re.search(r'R3-\\d+',q['question']).group() for q in qs if 'Follow its revisions' in q['question']}
with open('records/phase-1/tdocs.jsonld') as f: data=json.load(f)
g=data['@graph']; byid={x['@id']:x for x in g}; edges=collections.defaultdict(set)
def vals(v):return v if isinstance(v,list) else [v]
for x in g:
 for y in vals(x.get('revisedTo',[])):edges[x['@id']].add(y)
 for y in vals(x.get('isRevisionOf',[])):edges[y].add(x['@id'])
seen=set('tdoc:'+x for x in revroots); todo=list(seen)
while todo:
 for y in edges[todo.pop()]:
  if y not in seen: seen.add(y);todo.append(y)
print('REVISION EDGES')
for x in sorted(seen):print(x,sorted(edges[x]))
print('TARGET AND DESCENDANT TDOCS')
for x in sorted({'tdoc:'+x for x in roots}|seen):
 print(json.dumps(byid.get(x,{'missing':x}),ensure_ascii=False))
del data,g,byid
with open('records/phase-2/decision_dispositions.jsonld') as f:data=json.load(f)
g=data['@graph']
print('EVIDENCE COUNTS',collections.Counter(x['evidenceStatus'] for x in g))
print('SCOPE COUNTS',collections.Counter(json.loads(x['assessmentMethod']).get('scope') for x in g))
print('TARGET DISPOSITIONS')
for x in g:
 if x['dispositionTarget'] in seen or x['targetTdocNumber'] in roots:
  a=json.loads(x['assessmentMethod']);print(json.dumps({k:x[k] for k in ['dispositionOf','targetTdocNumber','dispositionCode','evidenceStatus','evidenceQuote']},ensure_ascii=False),json.dumps({'scope':a.get('scope'),'rule':a.get('rule')},ensure_ascii=False))
PY"

